local DreamSpace_Postprocessing = Class('DreamSpace_Postprocessing')
-- 外部调用时使用:
-- local DreamSpace_Postprocessing = import('Game.DreamSpace.Level1.DreamSpace_Postprocessing')


-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Camera = CS.UnityEngine.Camera
local Time = CS.UnityEngine.Time
local Mathf = CS.UnityEngine.Mathf


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils

local CameraCustomData = CS.CameraCustomData
local BaseSettingEnum = CameraCustomData.BaseSettingEnum

-- ========================================================


local currentInstance = nil

-- 正常游戏时的配置:
local commonSettings = {}
commonSettings.colorAdjustments = 
{
    postExposure = 1,
    contrast = 2,
    hueShift = 0, 
    saturation = 0,
}

commonSettings.vignette = 
{
    intensity = 0.2,
    smoothness = 0.353
}


-- 回忆时的配置:
local memorySettings = {} 
memorySettings.colorAdjustments = 
{
    postExposure = 1,
    contrast = 2, 
    hueShift = 0, 
    saturation = -100, -- 纯黑白
}

memorySettings.vignette = 
{
    intensity = 0.58, -- 半圆黑边
    smoothness = 0.4
}





-- ========================================================

function DreamSpace_Postprocessing:__init()
    self.controller = nil
    self.co_1 = nil   -- 发送携程请求
end


function DreamSpace_Postprocessing:__delete()
    self.co_1 = nil
end


function DreamSpace_Postprocessing:Awake()
    if currentInstance == nil then 
        currentInstance = self
    else 
        assert( false, "不允许存在 第二个 DreamSpace_Postprocessing 实例" )
    end 
end


function DreamSpace_Postprocessing:Start()
    KTool.SetActive(self.controller.gameObject, true)
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ==============================

    assert( self.cameraCustomData )

    -- 两个核心后处理 全部开启
    self.colorAdjustments = self.cameraCustomData.postProcess.colorAdjustments
    self.colorAdjustments.colorAdjustmentsState = BaseSettingEnum.Open

    self.vignette = self.cameraCustomData.postProcess.vignette
    self.vignette.vignetteState = BaseSettingEnum.Open

    self.tgtSettings = nil
end


function DreamSpace_Postprocessing:OnDestroy()
    currentInstance = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


function DreamSpace_Postprocessing.WaitInstance()
    -- 只等待有限帧
    for i=1,500 do 
        if isNotNull(currentInstance) then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    assert( isNotNull(currentInstance), "始终没能等到 DreamSpace_Postprocessing 实例化, 请检查场景" )
end


function DreamSpace_Postprocessing.GetInstance()
    return currentInstance
end


-- =========================================== Self ================================================ --


function DreamSpace_Postprocessing:Update()
    if self.isDirty == false  or self.tgtSettings == nil then 
        return
    end 

    self:UpdateColorAdjustments()
    self:UpdateVignette()
end

function DreamSpace_Postprocessing:SwitchToCommon( smoothTime )
    if type(smoothTime) == "number" then 
        self.smoothTime = smoothTime
    end 
    self.tgtSettings = commonSettings
    self.isDirty = true

    self.startTime = Time.time
    self.startColorAdjustments = self.colorAdjustments
    self.startVignette = self.vignette
end


function DreamSpace_Postprocessing:SwitchToMemory( smoothTime )
    if type(smoothTime) == "number" then 
        self.smoothTime = smoothTime
    end 
    self.tgtSettings = memorySettings
    self.isDirty = true

    self.startTime = Time.time
    self.startColorAdjustments = self.colorAdjustments
    self.startVignette = self.vignette
end


function DreamSpace_Postprocessing:GetIsDirty()
    return self.isDirty
end


-- 逐帧逼近:
function DreamSpace_Postprocessing:UpdateColorAdjustments()

    local tgtColorAdjustments = self.tgtSettings.colorAdjustments
    local t = (Time.time - self.startTime) / self.smoothTime

    if  Mathf.Approximately( self.colorAdjustments.postExposure, tgtColorAdjustments.postExposure ) and 
        Mathf.Approximately( self.colorAdjustments.contrast, tgtColorAdjustments.contrast ) and 
        Mathf.Approximately( self.colorAdjustments.hueShift, tgtColorAdjustments.hueShift ) and 
        Mathf.Approximately( self.colorAdjustments.saturation, tgtColorAdjustments.saturation )
    then
        self.isDirty = false 
        return
    end 

    self.colorAdjustments.postExposure  = Mathf.SmoothStep( self.startColorAdjustments.postExposure,   tgtColorAdjustments.postExposure, t )
    self.colorAdjustments.contrast      = Mathf.SmoothStep( self.startColorAdjustments.contrast,       tgtColorAdjustments.contrast,   t )
    self.colorAdjustments.hueShift      = Mathf.SmoothStep( self.startColorAdjustments.hueShift,       tgtColorAdjustments.hueShift,   t )
    self.colorAdjustments.saturation    = Mathf.SmoothStep( self.startColorAdjustments.saturation,     tgtColorAdjustments.saturation, t )    
end



function DreamSpace_Postprocessing:UpdateVignette()

    local tgtVignette = self.tgtSettings.vignette
    local t = (Time.time - self.startTime) / self.smoothTime

    -- 足够接近就停止
    if  Mathf.Approximately( self.vignette.intensity, tgtVignette.intensity ) and 
        Mathf.Approximately( self.vignette.smoothness, tgtVignette.smoothness )
    then 
        self.isDirty = false 
        return
    end 

    self.vignette.intensity     = Mathf.SmoothStep( self.startVignette.intensity,   tgtVignette.intensity, t )
    self.vignette.smoothness    = Mathf.SmoothStep( self.startVignette.smoothness,  tgtVignette.smoothness, t ) 
end






return DreamSpace_Postprocessing
